  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Chemical Reactions and Balancing Equations$j$, $j${"readings": [{"title": "Hebrews 1 (King James Version)", "url": "/portal/bible/Hebrews/1"}], "body": "A chemical reaction is a process in which one or more substances change into new substances. The starting materials are called reactants, and the new substances are called products. A chemical equation uses formulas to show a reaction, with reactants on the left, products on the right and the word yields or an arrow between them. Hebrews 1:3 says that Christ is upholding all things by the word of his power. The order we see in matter, including the way it is conserved in reactions, points to that faithful upholding.\n\nThe law of conservation of mass states that matter is neither created nor destroyed in an ordinary chemical reaction. The atoms in the reactants are rearranged into the products, so the number of atoms of each element must be the same on both sides. We balance equations by placing numbers called coefficients in front of formulas. We never change the small subscripts inside a formula, because that would change the substance. For example, hydrogen plus oxygen yields water is first written H2 plus O2 yields H2O. Oxygen is not balanced, so we write 2H2 plus O2 yields 2H2O. Now there are 4 hydrogen atoms and 2 oxygen atoms on each side.\n\nReactions fall into patterns. In a synthesis reaction, two or more substances combine into one. In a decomposition reaction, one compound breaks into simpler substances. In a single replacement reaction, one element replaces another in a compound. In a double replacement reaction, the ions of two compounds trade partners, often forming a precipitate, a gas or water. In a combustion reaction, a substance reacts rapidly with oxygen, releasing energy, as when a hydrocarbon burns to form carbon dioxide and water.\n\nYour task: (1) State the law of conservation of mass. (2) Balance: Mg plus O2 yields MgO. (3) Identify each reaction type: 2H2O yields 2H2 plus O2, and CH4 plus 2O2 yields CO2 plus 2H2O.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Hebrews 1:3 says that Christ is upholding all things by the word of his power. The order we see in matter points to that faithful upholding.\n\nNow watch this. A chemical reaction changes reactants into products. An equation shows the reactants on the left and the products on the right.\n\nThe law of conservation of mass says matter is neither created nor destroyed in an ordinary reaction. The atoms are rearranged, so each element must have the same number of atoms on both sides. We balance by placing coefficients in front of formulas. Never change the subscripts. H2 plus O2 yields H2O becomes 2H2 plus O2 yields 2H2O.\n\nTypes of reactions. Synthesis combines substances. Decomposition breaks one compound apart. Single replacement swaps one element for another. Double replacement trades partners and may form a precipitate, a gas or water. Combustion is rapid reaction with oxygen that releases energy.\n\nYour task is to state the law, balance magnesium plus oxygen and identify two reaction types. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Chemical Reactions and Balancing Equations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 The Mole and Molar Mass$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "Atoms and molecules are far too small to count one at a time, so chemists use a counting unit called the mole. One mole of anything contains 6.02 times 10 to the 23rd particles. This number is called Avogadro's number. A mole of carbon atoms, a mole of water molecules and a mole of sodium chloride formula units each contain 6.02 times 10 to the 23rd particles. The mole is like a dozen, but for atoms. Proverbs 16:11 reminds us of the honesty of correct amounts: A just weight and balance are the LORD'S.\n\nThe molar mass of a substance is the mass in grams of one mole of it. It is numerically equal to the atomic mass from the periodic table, in grams per mole. Carbon has a molar mass of about 12.0 grams per mole. To find the molar mass of a compound, add the molar masses of all the atoms in the formula. For water, H2O, add 2 times 1.0 for hydrogen and 16.0 for oxygen to get 18.0 grams per mole. For carbon dioxide, add 12.0 and 2 times 16.0 to get 44.0 grams per mole.\n\nMoles can be converted to grams and back. To change moles to grams, multiply by molar mass. To change grams to moles, divide by molar mass. For example, 36 grams of water divided by 18.0 grams per mole equals 2.0 moles. To change moles to particles, multiply by 6.02 times 10 to the 23rd. So 2.0 moles of water contain 1.2 times 10 to the 24th molecules.\n\nPercent composition tells what percentage of a compound's mass comes from each element. In water, hydrogen makes up 2.0 divided by 18.0, or about 11 percent, and oxygen makes up about 89 percent.\n\nYour task: (1) Find the molar mass of CaCO3 using Ca 40.1, C 12.0 and O 16.0. (2) Convert 88 grams of CO2 to moles. (3) Explain why chemists use the mole.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Proverbs 16:11 says, A just weight and balance are the LORD'S. Correct amounts matter.\n\nNow watch this. Atoms are too small to count one at a time, so chemists use the mole. One mole is 6.02 times 10 to the 23rd particles. That is Avogadro's number. The mole is like a dozen, but for atoms.\n\nMolar mass is the mass in grams of one mole. It equals the atomic mass from the periodic table, in grams per mole. For a compound, add the atoms in the formula. Water is 2 times 1.0 plus 16.0, which is 18.0 grams per mole. Carbon dioxide is 12.0 plus 2 times 16.0, which is 44.0.\n\nMoles to grams, multiply by molar mass. Grams to moles, divide by molar mass. Thirty six grams of water is 2.0 moles. Moles to particles, multiply by 6.02 times 10 to the 23rd.\n\nPercent composition tells the percentage of the mass from each element.\n\nYour task is to find the molar mass of calcium carbonate, convert 88 grams of carbon dioxide to moles and explain the mole. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 The Mole and Molar Mass$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Stoichiometry: Mole Ratios and Mass Calculations$j$, $j${"readings": [{"title": "Proverbs 25 (King James Version)", "url": "/portal/bible/Proverbs/25"}], "body": "Stoichiometry is the calculation of the amounts of reactants and products in a chemical reaction. It uses the balanced equation as a recipe. Proverbs 25:2 reminds us that it is the glory of God to conceal a thing, and a faithful scientist searches it out with careful work. A baker follows a recipe to make the right number of loaves, and a chemist follows the coefficients to predict the right amount of product.\n\nThe coefficients in a balanced equation give the mole ratio. In the reaction N2 plus 3H2 yields 2NH3, one mole of nitrogen reacts with three moles of hydrogen to make two moles of ammonia. The mole ratio of hydrogen to ammonia is 3 to 2. If 6 moles of hydrogen react, the amount of ammonia is 6 times 2 over 3, which is 4 moles.\n\nTo solve a mass problem, follow a pattern. First, write the balanced equation. Second, convert the given mass to moles using molar mass. Third, use the mole ratio from the coefficients to find moles of the wanted substance. Fourth, convert moles to grams with molar mass. For example, consider 2H2 plus O2 yields 2H2O. How many grams of water form from 4.0 grams of hydrogen? Hydrogen has a molar mass of 2.0 grams per mole, so 4.0 grams is 2.0 moles. The ratio of water to hydrogen is 2 to 2, so 2.0 moles of water form. Water has a molar mass of 18.0 grams per mole, so 2.0 moles is 36 grams.\n\nAlways write units, check that the answer is reasonable, and remember that mass is conserved: the total mass of the reactants equals the total mass of the products.\n\nYour task: (1) In 2H2 plus O2 yields 2H2O, find the moles of water from 3 moles of oxygen. (2) Describe the four steps for a mass to mass problem. (3) Explain why the balanced equation must come first.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Proverbs 25:2 says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter. A faithful scientist searches it out with careful work.\n\nNow watch this. Stoichiometry predicts the amounts of reactants and products. The balanced equation is the recipe, and the coefficients give the mole ratio.\n\nN2 plus 3H2 yields 2NH3. One mole of nitrogen reacts with three moles of hydrogen to make two moles of ammonia. If 6 moles of hydrogen react, you get 4 moles of ammonia.\n\nFor a mass problem. One, write the balanced equation. Two, convert grams to moles. Three, use the mole ratio. Four, convert moles to grams.\n\nExample. 2H2 plus O2 yields 2H2O. How many grams of water from 4.0 grams of hydrogen? That is 2.0 moles of hydrogen. The ratio is 2 to 2, so 2.0 moles of water. Times 18.0 grams per mole is 36 grams.\n\nWrite units. Check that the answer is reasonable. Mass is conserved.\n\nYour task is to find moles of water from 3 moles of oxygen, describe the four steps and explain why the equation comes first. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Stoichiometry: Mole Ratios and Mass Calculations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Limiting Reactants and Percent Yield$j$, $j${"readings": [{"title": "John 6 (King James Version)", "url": "/portal/bible/John/6"}], "body": "In real reactions, reactants are often not present in exactly the right proportions. The limiting reactant is the reactant that is used up first and so limits how much product can form. The reactant that remains is the excess reactant. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? A wise builder counts what supplies are on hand, and so does a chemist.\n\nThink of making sandwiches with 10 slices of bread and 4 slices of cheese, where each sandwich needs 2 slices of bread and 1 slice of cheese. The bread could make 5 sandwiches, but the cheese makes only 4, so the cheese is the limiting reactant. To find the limiting reactant, calculate how much product each reactant could make, using the balanced equation. The smaller amount of product shows the limiting reactant, and that smaller amount is the theoretical yield.\n\nFor example, in 2H2 plus O2 yields 2H2O, suppose there are 2 moles of hydrogen and 2 moles of oxygen. Two moles of hydrogen would need only 1 mole of oxygen, so hydrogen is limiting and oxygen is in excess. The 2 moles of hydrogen produce 2 moles of water.\n\nThe theoretical yield is the maximum amount of product predicted by the calculation. The actual yield is the amount actually obtained in the lab. Percent yield equals actual yield divided by theoretical yield, times 100. If the theoretical yield is 10.0 grams and 8.0 grams is obtained, the percent yield is 80 percent. Yields are lower than 100 percent because of incomplete reactions, side reactions and losses during collection. John 6:12 says, Gather up the fragments that remain, that nothing be lost. Industry works to reduce waste and improve yield.\n\nYour task: (1) Define limiting reactant. (2) Find the limiting reactant if 3 moles of hydrogen and 2 moles of oxygen react in 2H2 plus O2 yields 2H2O. (3) Calculate percent yield for an actual yield of 15 grams and a theoretical yield of 20 grams.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? A wise builder counts supplies, and so does a chemist.\n\nNow watch this. The limiting reactant is used up first and limits the product. The reactant left over is the excess reactant.\n\nWith 10 slices of bread and 4 slices of cheese, and each sandwich needing 2 bread and 1 cheese, the bread could make 5 sandwiches but the cheese only 4. The cheese is limiting.\n\nIn chemistry, calculate how much product each reactant could make. The smaller amount shows the limiting reactant and is the theoretical yield. For 2 moles of hydrogen and 2 moles of oxygen, hydrogen needs only 1 mole of oxygen, so hydrogen is limiting and makes 2 moles of water.\n\nPercent yield is actual yield divided by theoretical yield, times 100. Eight grams from a theoretical 10 grams is 80 percent. John 6:12 says, Gather up the fragments that remain, that nothing be lost.\n\nYour task is to define limiting reactant, find it for 3 moles hydrogen and 2 moles oxygen and calculate a percent yield. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Limiting Reactants and Percent Yield$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Chemical Reactions and Stoichiometry$j$, $j${"prompt": "Write a report of at least 250 words on chemical reactions and calculations. Use complete sentences and label each part. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?\n\nPart 1: State the law of conservation of mass and explain why we balance equations. Balance Na plus Cl2 yields NaCl, and C3H8 plus O2 yields CO2 plus H2O. Name the five types of reactions and give an example of each.\nPart 2: Define mole and Avogadro's number. Find the molar mass of Na2SO4 and calculate how many moles are in 71 grams of it, showing your work. Use Na 23.0, S 32.0 and O 16.0.\nPart 3: Using 2H2 plus O2 yields 2H2O, find the grams of water made from 8.0 grams of hydrogen, showing all steps.\nPart 4: Define limiting reactant, theoretical yield, actual yield and percent yield. Calculate percent yield when 18 grams are obtained from a theoretical 24 grams.\nPart 5: Explain how John 6:12 and Luke 14:28 apply to wise use of resources in industry and in life.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 20 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Chemical Reactions and Stoichiometry$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Counteth the Cost$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains in your own words why chemical equations must be balanced and how conservation of mass shows order in creation, (2) describes a real life situation, such as cooking, building or budgeting, where a limiting resource decides how much you can make, (3) explains why waste should be reduced in industry and at home, and (4) connects your answer to Hebrews 1:3, Luke 14:28 or John 6:12. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do you think the mole was invented? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Counteth the Cost$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Chemical Reactions and Balancing Equations$j$, $j${"questions": [{"q": "The law of conservation of mass says that in a chemical reaction:", "options": ["New atoms are made", "Mass always doubles", "Atoms are rearranged but not created or destroyed", "Mass is lost"]}, {"q": "When balancing an equation you may change:", "options": ["The reactants", "Coefficients", "Element symbols", "Subscripts"]}, {"q": "What coefficient goes in front of H2O in H2 plus O2 yields H2O when balanced as 2H2 plus O2 yields 2H2O?", "options": ["3", "4", "1", "2"]}, {"q": "A reaction in which a compound breaks into simpler substances is:", "options": ["Decomposition", "Combustion", "Double replacement", "Synthesis"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Chemical Reactions and Balancing Equations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,0}'::int[], array[$j$Atoms are conserved.$j$,$j$Only coefficients may be adjusted.$j$,$j$Two water molecules balance the oxygen.$j$,$j$Decomposition separates a compound.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Chemical Reactions and Balancing Equations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: The Mole and Molar Mass$j$, $j${"questions": [{"q": "One mole contains how many particles?", "options": ["6.02 times 10 to the 23rd", "One thousand", "6.02 times 10 to the 32nd", "One million"]}, {"q": "The molar mass of water is about:", "options": ["18.0 grams per mole", "34.0 grams per mole", "10.0 grams per mole", "16.0 grams per mole"]}, {"q": "To convert grams to moles you:", "options": ["Multiply by molar mass", "Add molar mass", "Divide by molar mass", "Divide by 6.02"]}, {"q": "How many moles are in 44 grams of CO2 (molar mass 44.0 grams per mole)?", "options": ["2.0", "1.0", "0.5", "44"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Mole and Molar Mass$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,1}'::int[], array[$j$Avogadro's number is 6.02 times 10 to the 23rd.$j$,$j$2 hydrogen plus 1 oxygen gives 18.0.$j$,$j$Moles equal grams divided by molar mass.$j$,$j$44 divided by 44 equals 1.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Mole and Molar Mass$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Stoichiometry: Mole Ratios and Mass Calculations$j$, $j${"questions": [{"q": "In N2 plus 3H2 yields 2NH3, the mole ratio of H2 to NH3 is:", "options": ["1 to 2", "3 to 2", "2 to 3", "1 to 3"]}, {"q": "The first step in a stoichiometry problem is to:", "options": ["Write the balanced equation", "Convert to particles", "Measure the volume", "Find percent yield"]}, {"q": "In 2H2 plus O2 yields 2H2O, how many moles of water form from 2 moles of oxygen?", "options": ["8", "4", "2", "1"]}, {"q": "Total mass of reactants compared to total mass of products is:", "options": ["Unrelated", "Smaller", "Greater", "Equal"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Stoichiometry: Mole Ratios and Mass Calculations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,3}'::int[], array[$j$Coefficients give the ratio.$j$,$j$The balanced equation gives the ratios.$j$,$j$Ratio of water to oxygen is 2 to 1.$j$,$j$Mass is conserved.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Stoichiometry: Mole Ratios and Mass Calculations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Limiting Reactants and Percent Yield$j$, $j${"questions": [{"q": "The reactant that is completely used up first is the:", "options": ["Excess reactant", "Product", "Catalyst", "Limiting reactant"]}, {"q": "Percent yield equals:", "options": ["Theoretical divided by actual, times 100", "Actual minus theoretical", "Actual plus theoretical", "Actual divided by theoretical, times 100"]}, {"q": "An actual yield of 8.0 grams and a theoretical yield of 10.0 grams gives a percent yield of:", "options": ["125 percent", "18 percent", "80 percent", "8 percent"]}, {"q": "The maximum amount of product a reaction can make is the:", "options": ["Percent yield", "Excess", "Theoretical yield", "Actual yield"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Limiting Reactants and Percent Yield$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,2,2}'::int[], array[$j$It limits how much product forms.$j$,$j$Percent yield compares actual to theoretical.$j$,$j$8 divided by 10 times 100 equals 80.$j$,$j$Theoretical yield comes from the calculation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Limiting Reactants and Percent Yield$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Chemical Reactions and Stoichiometry$j$, $j${"questions": [{"q": "In a chemical reaction the starting substances are the:", "options": ["Catalysts", "Isotopes", "Reactants", "Products"]}, {"q": "Which type of reaction produces carbon dioxide and water from a hydrocarbon and oxygen?", "options": ["Decomposition", "Single replacement", "Combustion", "Synthesis"]}, {"q": "A mole of any substance contains:", "options": ["6.02 times 10 to the 23rd particles", "100 particles", "One gram", "One liter"]}, {"q": "The molar mass of CO2 is about:", "options": ["44 grams per mole", "32 grams per mole", "12 grams per mole", "28 grams per mole"]}, {"q": "How many moles are in 36 grams of water?", "options": ["0.5", "2.0", "18", "1.0"]}, {"q": "In 2H2 plus O2 yields 2H2O, 3 moles of oxygen make how many moles of water?", "options": ["6", "3", "2", "1.5"]}, {"q": "The limiting reactant is the one that:", "options": ["Is a catalyst", "Runs out first", "Has the most mass", "Is left over"]}, {"q": "Percent yield of 15 grams actual and 20 grams theoretical is:", "options": ["75 percent", "25 percent", "5 percent", "133 percent"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Chemical Reactions and Stoichiometry$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,0,0,1,0,1,0}'::int[], array[$j$Reactants are on the left side.$j$,$j$Burning in oxygen is combustion.$j$,$j$Avogadro's number.$j$,$j$12 plus 2 times 16 equals 44.$j$,$j$36 divided by 18 equals 2.$j$,$j$The ratio of water to oxygen is 2 to 1.$j$,$j$It limits the product.$j$,$j$15 divided by 20 times 100 equals 75.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Chemical Reactions and Stoichiometry$j$ on conflict (item_id) do nothing;
